    void mutateLedger(Runnable action){
        long generation=Store.prefs(this).getLong("generation",0);
        if(!LedgerWork.submit(()->{try{synchronized(Store.class){if(Store.prefs(this).getLong("generation",0)!=generation)return;action.run();}runOnUiThread(()->{if(!isDestroyed())render();});}catch(RuntimeException e){runOnUiThread(()->{if(!isDestroyed())Toast.makeText(this,e instanceof IllegalArgumentException?e.getMessage():"Could not save. Your previous data is retained; reopen the form and try again.",Toast.LENGTH_LONG).show();});}}))Toast.makeText(this,"Ledger is busy. Please try again shortly.",Toast.LENGTH_LONG).show();
    }
