    void monthlyHistory(java.time.YearMonth month){
        long generation=Store.prefs(this).getLong("generation",0);
        if(!LedgerWork.submit(()->{
            try{
                java.time.ZoneId zone=java.time.ZoneId.systemDefault();long start=month.atDay(1).atStartOfDay(zone).toInstant().toEpochMilli(),end=month.plusMonths(1).atDay(1).atStartOfDay(zone).toInstant().toEpochMilli()-1;
                LedgerDb.MonthSummary summary;JSONArray priority;
                synchronized(Store.class){if(Store.prefs(this).getLong("generation",0)!=generation)return;LedgerDb db=LedgerDb.get(this);summary=db.month(start,end);priority=db.priorityReview(start,end);}
                runOnUiThread(()->{
                    if(isDestroyed()||Store.prefs(this).getLong("generation",0)!=generation)return;
                    LedgerDb.Outflow out=summary.outflow();
                    String content="From captured messages, using their arrival dates. This can be incomplete; possible duplicate alerts may remain.\n\nMoney in: "+Store.money(summary.moneyIn())+" (not automatically income)\nAll money out: "+Store.money(out.moneyOut())+"\nCash withdrawals: "+Store.money(out.cash())+"\nMarked transfers: "+Store.money(out.transfers())+"\nRemaining money out: "+Store.money(out.remaining())+"\n\n"+summary.entries()+" entries · "+summary.unreviewed()+" not reviewed.\nCash use is unknown. Remaining outflow can include unidentified transfers. No captured activity does not prove zero spending.";
                    LinearLayout box=new LinearLayout(this);box.setPadding(dp(20),dp(12),dp(20),dp(12));box.setOrientation(LinearLayout.VERTICAL);box.addView(text(content,14,ink,false));
                    if(priority.length()>0){Button review=new Button(this);review.setText(R.string.clarify_largest_entries);review.setOnClickListener(v->{String[] labels=new String[priority.length()];for(int i=0;i<labels.length;i++){JSONObject r=priority.optJSONObject(i);labels[i]=Store.money(r.optLong("paise"))+" · "+r.optString("merchant");}new AlertDialog.Builder(this).setTitle("Largest unreviewed entries").setItems(labels,(d,w)->edit(priority.optJSONObject(w))).setNegativeButton("Done",null).show();});box.addView(review);}
                    ScrollView scroll=new ScrollView(this);scroll.addView(box);
                    new AlertDialog.Builder(this).setTitle(month.toString()+" · message history").setView(scroll).setNegativeButton("Previous month",(d,w)->monthlyHistory(month.minusMonths(1))).setNeutralButton("Next month",(d,w)->monthlyHistory(month.plusMonths(1))).setPositiveButton("Done",null).show();
                });
            }catch(RuntimeException e){runOnUiThread(()->{if(!isDestroyed())Toast.makeText(this,"History unavailable. Try again after import.",Toast.LENGTH_LONG).show();});}
        }))Toast.makeText(this,"Ledger is busy. Try again shortly.",Toast.LENGTH_SHORT).show();
    }
