    void edit(JSONObject r) {
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(24),dp(8),dp(24),dp(8));
        box.addView(text("Type: "+r.optString("type","Unspecified")+" · "+r.optString("channel","Unspecified")+"\nName source: "+r.optString("nameSource","Unknown")+(!r.optString("vpa").isEmpty()?"\nUPI ID: "+r.optString("vpa"):"")+(!r.optString("reference").isEmpty()?"\nReference: "+r.optString("reference"):""),12,muted,false));
        box.addView(text("Source: "+r.optString("source")+"\nRecorded at: "+stamp(r.optLong("time"))+" ("+r.optString("timeSource","Source arrival timestamp")+")"+(!r.optString("messageDate").isEmpty()?"\nDate in message: "+r.optString("messageDate"):"")+(!r.optString("messageClock").isEmpty()?"\nClock in message: "+r.optString("messageClock")+" (timezone not established)":"\nExact transaction time not established")+(!r.optString("account").isEmpty()?"\nAccount/card: "+r.optString("issuer")+" "+r.optString("account"):""),12,muted,false));
        box.addView(text(r.has("originalPaise")?"Amount · you corrected it (message said "+Store.money(r.optLong("originalPaise"))+")":"Amount · as read from the message. Correct it if the message was misread.",12,muted,false));
        EditText amount=new EditText(this);amount.setHint("Amount in rupees");amount.setInputType(8194);amount.setText(java.math.BigDecimal.valueOf(r.optLong("paise"),2).stripTrailingZeros().toPlainString());box.addView(amount);
        EditText name=new EditText(this);name.setHint("Your name for this merchant or person");name.setText(r.optString("merchant"));box.addView(name);
        Spinner cat=new Spinner(this);String[] cats={"Other","Food & drink","Transport","Shopping","Entertainment","Subscriptions","Utilities","Housing","Recharge","Insurance","Groceries","Bills","Health","Transfer","Income","Money received","Refund","Interest","Cashback","Cash withdrawal","Fees","Debt repayment","Payment receipt","Not a transaction"};cat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cats));cat.setSelection(Math.max(0,java.util.Arrays.asList(cats).indexOf(r.optString("category"))));box.addView(cat);
        Spinner movement=new Spinner(this);movement.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Money out","Money in"}));movement.setSelection(r.optString("direction").equals("credit")?1:0);box.addView(movement);
        CheckBox remember=new CheckBox(this);remember.setText(r.optString("vpa").isEmpty()?R.string.remember_name:R.string.remember_upi);remember.setEnabled(!MerchantRules.key(r.optString("vpa"),r.optString("rawMerchant",r.optString("merchant"))).isEmpty());box.addView(remember);
        if(!remember.isEnabled())box.addView(text("There is no stable name or UPI ID to remember. This correction will apply to this entry only.",12,muted,false));
        int count=Store.matchingReviewCount(this,r);if(count>1){Button bulk=new Button(this);bulk.setText(getResources().getQuantityString(R.plurals.review_matching,count,count));bulk.setOnClickListener(v->{String category=cat.getSelectedItem().toString(),label=name.getText().toString().trim();if(label.isEmpty()||label.equals("Unknown merchant")){name.setError("Enter a name you recognise");return;}new AlertDialog.Builder(this).setTitle("Confirm "+count+" entries?").setMessage("Set matching extracted identities from this source, issuer and payment method to "+label+" / "+category+". Truncated names can belong to different shops. Confirm only if these are the same payee. Money direction stays unchanged.").setPositiveButton("Confirm group",(d,w)->{mutateLedger(()->Store.reviewMatching(this,r,label,category));}).setNegativeButton("Cancel",null).show();});box.addView(bulk);}
        Button reportButton=new Button(this);reportButton.setText(R.string.report_extraction_issue);reportButton.setOnClickListener(v->reportMessage(r));box.addView(reportButton);
        ScrollView scroll=new ScrollView(this);scroll.addView(box);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Review transaction").setView(scroll).setPositiveButton("Save",null).setNeutralButton("Delete",(d,w)->new AlertDialog.Builder(this).setTitle("Delete transaction?").setPositiveButton("Delete",(x,y)->{mutateLedger(()->Store.edit(this,r.optString("id"),"","",true));}).setNegativeButton("Cancel",null).show()).setNegativeButton("Cancel",null).create();
        // Validate before closing: a mistyped amount keeps the dialog and the user's other edits open.
        dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{long paise=Store.parseRupees(amount.getText().toString());if(paise<0){amount.setError("Enter a positive amount, with up to two decimal places");return;}String label=name.getText().toString().trim(),category=cat.getSelectedItem().toString(),direction=movement.getSelectedItemPosition()==1?"credit":"debit";boolean savedRule=remember.isChecked();mutateLedger(()->Store.review(this,r.optString("id"),label.isEmpty()?"Unknown merchant":label,category,direction,savedRule,paise));dialog.dismiss();}));
        dialog.show();
    }
    /** Not configured, denied, disconnected and active are different states; none of them is a zero. */
    String captureStatus(){
        boolean sms=Store.prefs(this).getBoolean("sms_capture",false)&&checkSelfPermission(android.Manifest.permission.RECEIVE_SMS)==android.content.pm.PackageManager.PERMISSION_GRANTED;
        boolean notifications=Store.prefs(this).getBoolean("capture",false);
        return "SMS capture: "+(sms?"on":Store.prefs(this).getBoolean("sms_capture",false)?"permission missing":"off")+" · Notifications: "+(!notifications?"off":CaptureService.isConnected()?"connected":"not connected")+(Store.prefs(this).getBoolean("capture_error",false)?" · some messages failed, see Settings":"");
    }
    String stamp(long time){return new java.text.SimpleDateFormat("dd MMM yyyy, HH:mm",java.util.Locale.UK).format(new java.util.Date(time));}
    void financialEvents(){
        JSONArray all=FinancialEvents.rows(this);java.util.List<JSONObject> sorted=new java.util.ArrayList<>();for(int i=0;i<all.length();i++)sorted.add(all.optJSONObject(i));sorted.sort(java.util.Comparator.comparingLong((JSONObject r)->r.optLong("time")).reversed());
        StringBuilder content=new StringBuilder("Message-stated events stay outside spending. Matching references can resolve a payment; otherwise confirm status yourself. Historical reminders may refer to the same bill.\n\n");int n=0;
        for(JSONObject r:sorted){if(n++>=80)break;content.append(r.optString("type")).append(" · ").append(r.optString("status","Open")).append(" · ").append(r.optString("kind","Payment")).append(r.optLong("amount")>0?" · "+Store.money(r.optLong("amount")):"").append("\n");if(!r.optString("dueDate").isEmpty())content.append("Stated date: ").append(r.optString("dueDate")).append("\n");content.append(r.optString("issuer")).append(" ").append(r.optString("account")).append("\nReceived: ").append(stamp(r.optLong("time"))).append(" · ").append(r.optString("source")).append("\n\n");}
        if(sorted.isEmpty())content.append("No financial events saved yet. Import SMS again to extract them from existing history.");
        new AlertDialog.Builder(this).setTitle("Financial events · latest 80").setMessage(content.toString()).setNeutralButton("Update a status",(d,w)->eventStatus()).setPositiveButton("Done",null).show();
    }
    void reportedBalances(){
        java.util.Map<String,JSONObject> latest=new java.util.TreeMap<>();JSONArray all=Store.rows(this);
        for(int i=0;i<all.length();i++){JSONObject row=all.optJSONObject(i);if(!row.has("reportedBalance")||row.optString("category").equals("Not a transaction")||row.optString("category").equals("Payment receipt")||!row.optString("source").equals("sms"))continue;latest.put(row.optString("issuer")+" "+row.optString("account"),row);}
        StringBuilder content=new StringBuilder("Bank-reported snapshots, not live balances. Masked account endings may overlap. Never calculated by adding transactions.\n\n");for(var e:latest.entrySet())content.append(e.getKey()).append("\n").append(Store.money(e.getValue().optLong("reportedBalance"))).append("\nSMS received: ").append(stamp(e.getValue().optLong("time"))).append("\n\n");if(latest.isEmpty())content.append("No supported balance snapshots yet. Re-import SMS to refresh extracted details.");new AlertDialog.Builder(this).setTitle("Last reported balances").setMessage(content.toString()).setPositiveButton("Done",null).show();
    }
