    void paste() {EditText field=new EditText(this);field.setHint("Paid INR 240 to Swiggy ref ABC123456");field.setMinLines(4);new AlertDialog.Builder(this).setTitle("Add from a message").setMessage("Processed locally. The original message is not saved. Remove personal information before pasting.").setView(field).setPositiveButton("Preview",(d,w)->{
        String message=field.getText().toString();TransactionParser.Parsed p=SourcePolicy.parse(message,null,"manual");
        if(p==null){new AlertDialog.Builder(this).setTitle("Nothing to add").setMessage("No completed payment found. Paynotes does not guess when an amount sits next to a balance or limit, when a message has more than one possible amount, or for pending, failed and scheduled payments.").setPositiveButton("OK",null).show();return;}
        new AlertDialog.Builder(this).setTitle("Add this entry?").setMessage((p.direction().equals("credit")?"Money in  +":"Money out  −")+Store.money(p.paise())+"\n"+p.merchant()+" · "+p.category()+" · "+p.channel()+"\n\nYou can correct the amount, name and category after saving.").setPositiveButton("Save",(x,y)->mutateLedger(()->{String result=Store.capture(this,message,"manual",System.currentTimeMillis());runOnUiThread(()->{if(!isDestroyed())Toast.makeText(this,result,Toast.LENGTH_LONG).show();});})).setNegativeButton("Cancel",null).show();
    }).setNegativeButton("Cancel",null).show();}
