    void requestAi(java.util.List<InsightEngine.Insight> findings) {
        if(findings.isEmpty()){Toast.makeText(this,"No evidence-backed patterns to explain yet",Toast.LENGTH_SHORT).show();return;}
        String endpoint=Store.prefs(this).getString("ai_endpoint","");String token;
        try{token=SecureConfig.token(this);}catch(Exception e){aiStatus="Could not unlock the pilot token. Configure the connection again.";render();return;}
        if(endpoint.isEmpty()||token.isEmpty()){configureAi();return;}
        try{
            JSONObject payload=Insights.cloudPayload(findings);String snapshot=payload.toString();String accessToken=token;long generation=Store.prefs(this).getLong("generation",0);
            new AlertDialog.Builder(this).setTitle("Send these facts for AI explanation?").setMessage("Destination: "+endpoint+"\n\nYour pilot server forwards these numerical facts to OpenAI. Amounts and spending patterns are financial data. SMS bodies, senders, merchants, and account references are excluded.\n\nExact payload:\n"+payload.toString(2)).setPositiveButton("Send and explain",(d,w)->{
                aiBusy=true;aiStatus="Generating…";render();Context app=getApplicationContext();
                new Thread(()->{try{java.util.Map<String,String> answer=AiClient.explain(endpoint,accessToken,payload);runOnUiThread(()->{aiBusy=false;if(Store.prefs(app).getLong("generation",0)!=generation||isDestroyed())return;aiExplanations=answer;aiSnapshot=snapshot;aiStatus="AI explanations generated for this snapshot.";render();});}catch(Exception e){runOnUiThread(()->{aiBusy=false;if(isDestroyed()||Store.prefs(app).getLong("generation",0)!=generation)return;aiStatus="AI explanations unavailable. Check your connection, server configuration, and access token. Local insights still work.";render();});}},"ai-explanations").start();
            }).setNegativeButton("Cancel",null).show();
        }catch(JSONException e){Toast.makeText(this,"Could not prepare insight facts",Toast.LENGTH_SHORT).show();}
    }
    void configureAi() {
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(24),dp(8),dp(24),dp(8));EditText endpoint=new EditText(this);endpoint.setHint("https://your-server/insights");endpoint.setText(Store.prefs(this).getString("ai_endpoint",""));box.addView(endpoint);EditText token=new EditText(this);token.setHint("Server access token (not your OpenAI key)");token.setInputType(129);box.addView(token);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("AI connection").setMessage("The provider API key stays on your server. Enter the private pilot access token here. Saving does not send data.").setView(box).setPositiveButton("Save",null).setNeutralButton("Disconnect",(d,w)->{Store.prefs(this).edit().remove("ai_endpoint").remove("ai_token").apply();aiExplanations.clear();aiSnapshot="";aiStatus="Disconnected";render();}).setNegativeButton("Cancel",null).create();
        dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{java.net.URI uri=new java.net.URI(endpoint.getText().toString().trim());if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null)throw new Exception();String value=token.getText().toString().trim();if(value.isEmpty())value=SecureConfig.token(this);if(value.length()<24) {token.setError("Enter the server's pilot token (at least 24 characters)");return;}SecureConfig.save(this,value);Store.prefs(this).edit().putString("ai_endpoint",uri.toString()).apply();aiExplanations.clear();aiSnapshot="";aiStatus="Connection saved. No data has been sent.";dialog.dismiss();render();}catch(Exception e){endpoint.setError("Use a valid HTTPS endpoint; credentials must be entered separately");}}));dialog.show();
    }
