    void patterns(){
        line("LEARN FROM THE MESSAGES",11,muted,true);line("Message pattern lab",28,ink,true);
        line("Studies all available SMS folders on this phone. The ledger imports only received completed transactions. Results contain counts and grammar with names, IDs and numbers masked. Nothing is sent online.",14,muted,false);
        button(studyBusy?"Studying messages…":"Run full message study",()->{if(studyBusy)return;if(checkSelfPermission(android.Manifest.permission.READ_SMS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){Toast.makeText(this,"Grant inbox access in Settings first",Toast.LENGTH_SHORT).show();return;}studyBusy=true;studyStatus="Scanning all SMS folders locally…";render();Context app=getApplicationContext();long generation=Store.prefs(app).getLong("generation",0);new Thread(()->{String status;try{PatternLab.scan(app,generation,count->runOnUiThread(()->{if(isDestroyed())return;studyStatus="Studied "+count+" messages…";if(tab.equals("Patterns"))render();}));status="Study saved. Compare snapshots below.";}catch(Exception e){status="Study stopped. Check SMS permission and try again.";}String message=status;runOnUiThread(()->{studyBusy=false;if(isDestroyed())return;studyStatus=message;if(tab.equals("Patterns"))render();});},"pattern-study").start();});
        if(!studyStatus.isEmpty())line(studyStatus,13,muted,false);
        Switch learning=new Switch(this);learning.setText(R.string.learn_notification_patterns);learning.setChecked(Store.prefs(this).getBoolean("learn_patterns",false));learning.setOnCheckedChangeListener((b,on)->Store.prefs(this).edit().putBoolean("learn_patterns",on).apply());page.addView(learning);
        line("Keeps up to 100 distinct masked grammar patterns from active and new notifications while capture is enabled. No raw notification text is retained. Learned notification patterns: "+PatternLab.notificationShapes(this),12,muted,false);
        JSONArray history=PatternLab.history(this);
        if(history.length()>0){JSONObject latest=history.optJSONObject(history.length()-1);space(16);line("Latest study · parser v"+latest.optInt("parserVersion"),20,ink,true);line(latest.optInt("total")+" messages · "+latest.optInt("received")+" received · "+latest.optInt("sent")+" sent",15,ink,true);line(latest.optInt("candidates")+" received transaction candidates · "+latest.optInt("unknown")+" missing names · "+latest.optInt("missingReference")+" missing references",14,muted,false);
            line("Message families · all folders",18,ink,true);JSONObject families=latest.optJSONObject("families");if(families!=null)for(java.util.Iterator<String> it=families.keys();it.hasNext();){String key=it.next();line(key+"  ·  "+families.optInt(key),14,ink,false);}
            space(12);line("Patterns to improve",18,ink,true);JSONArray patterns=latest.optJSONArray("patterns");if(patterns!=null)for(int i=0;i<Math.min(10,patterns.length());i++){JSONObject p=patterns.optJSONObject(i);line(p.optString("family")+" · "+p.optInt("count")+" messages",14,green,true);line(p.optString("shape"),12,muted,false);}
            space(12);line("Study history · last five",18,ink,true);for(int i=history.length()-1;i>=0;i--){JSONObject snap=history.optJSONObject(i);line(new java.text.SimpleDateFormat("dd MMM, HH:mm",java.util.Locale.UK).format(new java.util.Date(snap.optLong("at")))+" · v"+snap.optInt("parserVersion")+" · "+snap.optInt("candidates")+" candidates · "+snap.optInt("unknown")+" missing names",12,muted,false);}
        }
        space(16);line("Resolve names without guessing",18,ink,true);line("A UPI suffix identifies a payment-service handle, not the merchant's identity or business category. Use the name in the message, correlate matching references, or save your own name and category in Activity. Unknown identities stay unresolved. No UPI ID is searched online automatically.",14,muted,false);
        button("Review missing names",()->{reviewFilter="Missing name";tab="Activity";render();});button("Back to Settings",()->{tab="Settings";render();});
    }
    void notificationControls(){
        line("You can also import transaction details from notifications that are still visible. Android does not provide an archive of dismissed notifications through this access.",13,muted,false);
        button(notificationBusy?"Checking active notifications…":"Import active notifications",()->{if(notificationBusy)return;if(!Store.prefs(this).getBoolean("capture",false)){Toast.makeText(this,"Enable notification capture first",Toast.LENGTH_SHORT).show();return;}notificationBusy=true;notificationStatus="Checking on this phone…";render();new Thread(()->{String status;try{CaptureService.Snapshot stats=CaptureService.importActive();status="Checked "+stats.active()+" active notifications · "+stats.added()+" added · "+stats.duplicates()+" duplicates ignored.";}catch(Exception e){status="Notification access is not connected. Check Android notification access and try again.";}String result=status;runOnUiThread(()->{notificationBusy=false;if(isDestroyed())return;notificationStatus=result;render();});},"active-notifications").start();});
        if(!notificationStatus.isEmpty())line(notificationStatus,13,muted,false);
    }
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==203){boolean read=checkSelfPermission(android.Manifest.permission.READ_SMS)==android.content.pm.PackageManager.PERMISSION_GRANTED;boolean receive=checkSelfPermission(android.Manifest.permission.RECEIVE_SMS)==android.content.pm.PackageManager.PERMISSION_GRANTED;Store.prefs(this).edit().putBoolean("sms_capture",read||receive).apply();if(read){importSms();}else{importStatus=receive?"New messages connected. Inbox access wasn't granted; you can enable it in Android permissions.":"Message access wasn't granted. You can still add payments manually.";Store.prefs(this).edit().putString("import_summary",importStatus).apply();render();Toast.makeText(this,importStatus,Toast.LENGTH_LONG).show();}return;}if(request!=201&&request!=202)return;boolean granted=grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED;if(granted){Store.prefs(this).edit().putBoolean("sms_capture",true).apply();if(request==202){importSms();return;}}else importStatus="SMS permission was not granted. Notification capture and manual paste are still available. You can review permissions in Android app settings.";render();}
    void importSms(){if(importBusy)return;importBusy=true;importStatus="Scanning SMS locally…";Store.prefs(this).edit().putString("import_summary",importStatus).apply();render();Context app=getApplicationContext();long generation=Store.prefs(app).getLong("generation",0);new Thread(()->{String result;try{SmsImport.Result stats=SmsImport.recent(app,importDays,generation);result="Scanned "+stats.scanned()+" messages · "+stats.added()+" added · "+stats.duplicate()+" duplicates ignored · "+stats.refreshed()+" refreshed · "+stats.excluded()+" excluded or previously deleted."+(stats.truncated()?" Stopped at the 5,000-message limit.":"");}catch(SecurityException e){result="SMS permission is unavailable or was revoked. No further messages were read.";}catch(Exception e){result="Import stopped. Capture may have been disabled or the SMS inbox is unavailable.";}String status=result;importBusy=false;if(generation==Store.prefs(app).getLong("generation",0))Store.prefs(app).edit().putString("import_summary",status).apply();runOnUiThread(()->{if(isDestroyed()||generation!=Store.prefs(app).getLong("generation",0))return;importStatus=status;render();Toast.makeText(this,status,Toast.LENGTH_LONG).show();});},"sms-import").start();}
    void feedback(String key){Store.prefs(this).edit().putInt(key,Store.prefs(this).getInt(key,0)+1).apply();Toast.makeText(this,"Feedback saved on this device",Toast.LENGTH_SHORT).show();}
    void settings() { ui().settings(); }
    void pilotControls(){
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(8),dp(20),dp(8));
        box.addView(text("Optional development feedback: share counts, source coverage, registered business sender codes (such as IDFCFB), masked message grammar and correction labels. When you correct an entry, a masked correction case can be queued automatically. No names, amounts, references, accounts, OTPs or message bodies are uploaded. Background sync runs about every six hours when Android allows it. Stop sharing at any time; server data expires after 90 inactive days.",14,muted,false));
        EditText url=new EditText(this);url.setHint("https://your-pilot-server");url.setSingleLine(true);url.setText(Store.prefs(this).getString("pilot_url",""));box.addView(url);
        EditText code=new EditText(this);code.setHint("Enrollment code from pilot admin");code.setSingleLine(true);box.addView(code);
        CheckBox consent=new CheckBox(this);consent.setText(R.string.pilot_consent);consent.setChecked(Store.prefs(this).getBoolean("pilot_consent",false));box.addView(consent);
        long last=Store.prefs(this).getLong("pilot_last_sync",0);box.addView(text(last==0?"No successful sync yet":"Last successful sync: "+stamp(last),12,muted,false));
        Button preview=new Button(this);preview.setText(R.string.preview_shared_data);preview.setOnClickListener(v->{try{new AlertDialog.Builder(this).setTitle("Diagnostic payload").setMessage(Learning.snapshot(this).toString(2)).setPositiveButton("OK",null).show();}catch(Exception e){Toast.makeText(this,"Preview unavailable",Toast.LENGTH_SHORT).show();}});box.addView(preview);
        Button sync=new Button(this);sync.setText(R.string.join_sync);sync.setOnClickListener(v->{if(!consent.isChecked()){Toast.makeText(this,"Agree to sharing or leave it disabled",Toast.LENGTH_SHORT).show();return;}try{String endpoint=PilotSync.base(url.getText().toString()),enrollmentCode=code.getText().toString();Store.prefs(this).edit().putBoolean("pilot_consent",true).apply();runPilotTask(()->{if(!enrollmentCode.trim().isEmpty()||Store.prefs(this).getString("pilot_installation","").isEmpty()||!endpoint.equals(Store.prefs(this).getString("pilot_url","")))PilotSync.enroll(this,endpoint,enrollmentCode);else {PilotSync.schedule(this);PilotSync.sync(this);}},"Synced. Your reports are visible in the pilot admin.");}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});box.addView(sync);
        Button pause=new Button(this);pause.setText(R.string.stop_sharing);pause.setOnClickListener(v->{PilotSync.pause(this);consent.setChecked(false);Toast.makeText(this,"Sharing stopped. An in-flight upload may finish. Shared server data remains until deleted or expired.",Toast.LENGTH_LONG).show();});box.addView(pause);
        Button remove=new Button(this);remove.setText(R.string.delete_shared_data);remove.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Remove server data?").setMessage("Deletes this installation's snapshots and reports and stops sharing. Your local ledger stays on this phone.").setPositiveButton("Delete",(d,w)->runPilotTask(()->PilotSync.removeRemote(this),"Shared data deleted; sharing stopped.")).setNegativeButton("Cancel",null).show());box.addView(remove);
        Button results=new Button(this);results.setText(R.string.pilot_progress);results.setOnClickListener(v->{try{JSONObject status=new JSONObject(Store.prefs(this).getString("pilot_status","{}"));StringBuilder t=new StringBuilder();JSONArray reports=status.optJSONArray("reports");if(reports!=null)for(int i=0;i<reports.length();i++){JSONObject r=reports.optJSONObject(i);t.append(r.optString("id").substring(0,8)).append(" · ").append(r.optString("state")).append(r.optInt("fixedVersion")>0?" · fixed in parser "+r.optInt("fixedVersion"):"").append("\n");}JSONObject release=status.optJSONObject("release");if(release!=null)t.append("Available: ").append(release.optString("versionName")).append(" · current "+BuildConfig.VERSION_NAME+"\nUpdates are installed by you after download.");AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle("Pilot progress").setMessage(t.length()==0?"Sync to check report progress and the latest app.":t.toString()).setPositiveButton("Done",null);if(release!=null&&release.optInt("versionCode")>BuildConfig.VERSION_CODE)b.setNeutralButton("Download update",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(PilotSync.base(Store.prefs(this).getString("pilot_url",""))+"/v1/app.apk"))));b.show();}catch(Exception e){Toast.makeText(this,"Sync first",Toast.LENGTH_SHORT).show();}});box.addView(results);
        ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle("Development pilot").setView(scroll).setPositiveButton("Done",null).show();
    }
    interface PilotAction {void run() throws Exception;}
    void runPilotTask(PilotAction action,String success){new Thread(()->{String result;try{action.run();result=success;}catch(Exception e){result="Could not sync: "+e.getMessage()+". Your data stays local; retry when the server is available.";}String message=result;runOnUiThread(()->{if(!isDestroyed())new AlertDialog.Builder(this).setMessage(message).setPositiveButton("OK",null).show();});},"pilot-action").start();}
    void reportMessage(JSONObject row){
        if(!Store.prefs(this).getBoolean("pilot_consent",false)){Toast.makeText(this,"Join the development pilot first",Toast.LENGTH_LONG).show();return;}
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);EditText body=new EditText(this);body.setHint("Paste a missed message locally; only masked grammar will be sent");if(row==null)box.addView(body);
        String[] issues={"wrong_amount","wrong_direction","wrong_name","wrong_category","not_transaction","missing_transaction","duplicate","missed_recurring","other"};Spinner issue=new Spinner(this);issue.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,issues));box.addView(issue);
        String[] expected={"unknown","debit","credit","receipt","event","ignore"};Spinner expect=new Spinner(this);expect.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,expected));box.addView(expect);
        new AlertDialog.Builder(this).setTitle("Report a message format").setView(box).setPositiveButton("Preview",(d,w)->{String raw=body.getText().toString();String shape=row==null?MessagePatterns.shape(raw):row.optString("shape");if(shape.isEmpty()||row==null&&MessagePatterns.family(raw).equals("OTP / verification")){Toast.makeText(this,"No shareable pattern; OTPs are excluded. Re-import old entries to populate grammar.",Toast.LENGTH_LONG).show();return;}String issuer=row==null?Issuer.inText(raw):row.optString("issuer");body.getText().clear();String choice=issue.getSelectedItem().toString(),want=expect.getSelectedItem().toString();new AlertDialog.Builder(this).setTitle("Only this grammar is shared").setMessage(shape+"\nIssue: "+choice+"\nExpected: "+want+"\nNo amounts, names, references or original text.").setPositiveButton("Submit",(x,y)->{Learning.report(this,shape,issuer,choice,want);runPilotTask(()->PilotSync.sync(this),"Report sent. Check progress in Development pilot.");}).setNegativeButton("Cancel",null).show();}).setNegativeButton("Cancel",null).show();
    }
    void eventStatus(){JSONArray a=FinancialEvents.rows(this);java.util.List<JSONObject> list=new java.util.ArrayList<>();for(int i=a.length()-1;i>=0&&list.size()<80;i--)list.add(a.optJSONObject(i));String[] labels=list.stream().map(e->e.optString("type")+" · "+e.optString("dueDate")+" · "+e.optString("issuer")+" · "+Store.money(e.optLong("amount"))).toArray(String[]::new);new AlertDialog.Builder(this).setTitle("Select evidence").setItems(labels,(d,w)->{JSONObject e=list.get(w);String[] states={"Open","Paid / received","Cancelled","Dismissed"};new AlertDialog.Builder(this).setTitle("You confirm the status").setItems(states,(x,y)->{FinancialEvents.resolve(this,e.optString("id",e.optString("fingerprint")),states[y]);render();}).show();}).show();}
    void commitments(){
        java.util.List<RecurringEngine.Payment> payments=new java.util.ArrayList<>();JSONArray all=LedgerDb.get(this).recent(System.currentTimeMillis()-800L*86400000L,false);for(int i=0;i<all.length();i++){JSONObject r=all.optJSONObject(i);if(!r.optString("direction").equals("debit")||r.optString("source").equals("sample"))continue;String identity=r.optString("source")+"|"+r.optString("issuer")+"|"+r.optString("account")+"|"+r.optString("merchant").trim().toLowerCase(java.util.Locale.ROOT);payments.add(new RecurringEngine.Payment(r.optString("id"),identity,r.optString("merchant"),r.optString("category"),r.optLong("paise"),java.time.Instant.ofEpochMilli(r.optLong("time")).atZone(java.time.ZoneId.systemDefault()).toLocalDate(),r.optBoolean("reviewed")));}
        java.util.List<RecurringEngine.Series> series=RecurringEngine.analyze(payments,java.time.LocalDate.now());LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(10),dp(20),dp(10));box.addView(text("Candidates from payment intervals. Announced bills are separate in Financial events. Amount ranges are past charges; mandate ceilings are not forecasts. Same merchant can represent multiple services.",14,muted,false));
        for(RecurringEngine.Series r:series){String key="series_"+Store.fingerprint(r.identity(),0);String state=Store.prefs(this).getString(key,"Needs confirmation");box.addView(text(r.merchant()+" · "+r.kind()+" · "+state,17,green,true));box.addView(text(r.cadence()+" · estimated next "+r.next()+"\n"+(r.variable()?"Past range "+Store.money(r.low())+"–"+Store.money(r.high()):"Last paid "+Store.money(r.latest()))+"\n"+r.evidence(),14,ink,false));Button status=new Button(this);status.setText(R.string.recurring_status);status.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(r.merchant()).setItems(new String[]{"Confirmed recurring","Paused","Cancelled","Not recurring"},(d,w)->{Store.prefs(this).edit().putString(key,new String[]{"Confirmed recurring","Paused","Cancelled","Not recurring"}[w]).apply();Toast.makeText(this,"Saved. This does not cancel a provider mandate.",Toast.LENGTH_LONG).show();}).show());box.addView(status);}
        if(series.isEmpty())box.addView(text("No supported recurring series yet. Two observations can suggest a candidate; review the payments and confirm with your provider. Missing messages can hide a series.",14,muted,false));ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle("Recurring payments").setView(scroll).setPositiveButton("Done",null).show();
    }

    void paymentChecks(){
        StringBuilder text=new StringBuilder("Checks are prompts for your review, not proof of fraud. No entries are removed automatically.\n\n");JSONArray events=FinancialEvents.rows(this);int requests=0,failures=0;long since=System.currentTimeMillis()-86400000L;
        for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if(e.optLong("time")<since||!e.optString("status","Open").equals("Open"))continue;if(e.optString("type").equals("Payment request"))requests++;if(e.optString("type").equals("Failed payment"))failures++;}
        text.append(requests).append(" payment requests in the last day. A request is not an authorised debit; check the requesting app.\n").append(failures).append(" failed-payment notices in the last day. Repeated notices may describe the same attempt.\n\n");
        java.util.List<PaymentChecks.Movement> input=new java.util.ArrayList<>();JSONArray a=LedgerDb.get(this).recent(since,false);for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(!r.optString("direction").equals("debit")||java.util.List.of("Transfer","Payment receipt","Not a transaction").contains(r.optString("category"))||r.optString("source").equals("sample"))continue;input.add(new PaymentChecks.Movement(r.optString("id"),r.optString("issuer"),r.optString("account"),r.optString("merchant"),r.optString("reference"),r.optLong("paise"),r.optLong("time")));}
        var flags=PaymentChecks.possibleDoublePayments(input);for(var f:flags)text.append(f.explanation()).append("\nEntries: ").append(f.firstId().substring(0,8)).append(" / ").append(f.secondId().substring(0,8)).append("\n\n");if(flags.isEmpty())text.append("No supported possible double-payment pair found. This does not prove that all charges are correct.");
        new AlertDialog.Builder(this).setTitle("Payment checks").setMessage(text.toString()).setPositiveButton("Done",null).show();
    }

